const Toggle = event({ payload: z.object({}) })

const m = machine({
  context: z.object({}),
  initialContext: {},
  initial: 'off',
  states: () => ({
    off: { on: [on(Toggle, { target: 'on' })] },
    on: { on: [on(Toggle, { target: 'off' })] },
  }),
})

contract(m, {
  given: { state: 'off' },
  when: [{ send: Toggle, payload: {} }],
  expect: { state: 'on' },
})
